                page.wait_for_timeout(100)
                assert page.evaluate("document.documentElement.scrollWidth <= innerWidth")
                page.screenshot(path=str(root / f"evidence/ui/{name}-{width}.png"), full_page=True)

        try:
            with sync_playwright() as p:
